    "expected_return": {
     "format": "json",
     "contract": "The registered handler returns its structured domain result and status; a successful write additionally returns its saved receipt with the definition's ID and revision. A provider tool call alone is not a saved result."
    },
    "card_description": "Use when a joint needs hardware the catalog does not have. Gives a new project material with its kind, counting and nominal size, and the exact ID and revision to put in the joint's fasteners.",
    "optional_parameters": [],
    "required_parameters": [
     "key",
     "name",
     "kind",
     "counting",
     "material_category",
     "diameter_mm",
     "length_mm",
     "request_quote"
    ],
    "additional_description": "Name it as the material list should show it. kind is one word for what it is, the same word each time, since totals group by it. counting: along_contact items are spaced along the contact and counted by the database from their size; per_joint items take the count you give each joint; per_construction is one package for the whole construction. The size is nominal, your design choice, not a measurement."
   }
  }
