   "replace": [
    {
     "field": "description",
     "old": "You choose parts and typed joints and save this shared checkpoint;",
     "new": "You choose parts, joints and what holds them, and save this shared checkpoint;"
    },
    {
     "field": "description",
     "old": "Joints name box faces in LOCAL part coordinates; methods/reasons are unverified design choices.",
     "new": "Joints name box faces in LOCAL part coordinates."
    },
    {
     "field": "additional_description",
     "old": "Joint methods are design choices, not checked strength or hardware. ",
     "new": ""
    },
    {
     "field": "additional_description",
     "old": "declared joint endpoints/methods",
     "new": "declared joint endpoints and fasteners"
    },
    {
     "field": "additional_description",
     "old": "Joint fastener: null applies the fixed rule (a screw sized from the board thickness; glue for glued joints). Set a fastener only for an owner choice such as nails, with kind, diameter_mm and length_mm; leave count and spacing_mm null to spread them by rule. Sending null removes an earlier choice. A joint between two existing parts (both role existing_part) gets no new fastener unless you set one.",
     "new": "What holds each joint is your choice: find_catalog_materials finds what the catalog has, and add_catalog_fastener adds the hardware it lacks. The database measures each chosen item against the joint it holds and shows the facts per item in the construction check; where a fact speaks against an item, choose again or keep the joint open. A joint between two existing parts needs nothing new."
    },
    {
     "field": "card_description",
     "old": "parts, materials and typed joints",
     "new": "parts, materials, joints and what holds them"
    }
   ]
